import { describe, expect, it } from 'vitest';
import { z } from 'zod';
import { CursorQuerySchema, decodeCursor, encodeCursor, pageSchema, paginate } from '../../src/lib/pagination.ts';
import { HttpProblem } from '../../src/lib/problem.ts';

const items = Array.from({ length: 45 }, (_, i) => ({ id: `item-${String(i).padStart(3, '0')}` }));
const key = (item: { id: string }): string => item.id;

describe('CursorQuerySchema', () => {
  it('defaults limit to 20 and coerces query strings', () => {
    expect(CursorQuerySchema.parse({})).toEqual({ limit: 20 });
    expect(CursorQuerySchema.parse({ limit: '5', cursor: 'abc' })).toEqual({ limit: 5, cursor: 'abc' });
  });

  it('rejects limits outside 1..100 and empty cursors', () => {
    expect(CursorQuerySchema.safeParse({ limit: '0' }).success).toBe(false);
    expect(CursorQuerySchema.safeParse({ limit: '101' }).success).toBe(false);
    expect(CursorQuerySchema.safeParse({ limit: '2.5' }).success).toBe(false);
    expect(CursorQuerySchema.safeParse({ cursor: '' }).success).toBe(false);
  });
});

describe('cursors', () => {
  it('round-trips a key through an opaque base64url cursor', () => {
    const cursor = encodeCursor('2024-01-01T00:00:00.000Z|abc');
    expect(cursor).toMatch(/^[A-Za-z0-9_-]+$/);
    expect(decodeCursor(cursor)).toBe('2024-01-01T00:00:00.000Z|abc');
  });

  it('rejects cursors it did not issue with a 422 problem', () => {
    for (const bad of ['not-a-cursor', Buffer.from('{"x":1}').toString('base64url')]) {
      try {
        decodeCursor(bad);
        expect.unreachable('decodeCursor should throw');
      } catch (err) {
        expect(err).toBeInstanceOf(HttpProblem);
        expect(err instanceof HttpProblem ? err.status : 0).toBe(422);
      }
    }
  });
});

describe('paginate', () => {
  it('walks every item exactly once, in key order', () => {
    const seen: string[] = [];
    let cursor: string | undefined;
    let pages = 0;
    do {
      const page = paginate(items, CursorQuerySchema.parse({ limit: '20', cursor }), key);
      seen.push(...page.data.map(key));
      cursor = page.nextCursor ?? undefined;
      pages += 1;
    } while (cursor !== undefined);
    expect(pages).toBe(3);
    expect(seen).toEqual(items.map(key));
  });

  it('returns nextCursor null on the last page', () => {
    const page = paginate(items.slice(0, 3), CursorQuerySchema.parse({}), key);
    expect(page.data).toHaveLength(3);
    expect(page.nextCursor).toBeNull();
  });

  it('does not depend on input order and survives deletion of the cursor item', () => {
    const shuffled = [...items].reverse();
    const first = paginate(shuffled, CursorQuerySchema.parse({ limit: 2 }), key);
    expect(first.data.map(key)).toEqual(['item-000', 'item-001']);
    const withoutLast = shuffled.filter((item) => item.id !== 'item-001');
    const second = paginate(withoutLast, CursorQuerySchema.parse({ limit: 2, cursor: first.nextCursor }), key);
    expect(second.data.map(key)).toEqual(['item-002', 'item-003']);
  });

  it('builds a page schema with data and nextCursor', () => {
    const schema = pageSchema(z.object({ id: z.string() }));
    expect(schema.parse({ data: [{ id: 'a' }], nextCursor: null })).toEqual({ data: [{ id: 'a' }], nextCursor: null });
    expect(schema.safeParse({ data: [{ id: 1 }], nextCursor: null }).success).toBe(false);
  });
});

import express from 'express';
import request from 'supertest';
import type { Response } from 'supertest';
import { afterEach, describe, expect, it, vi } from 'vitest';
import { z } from 'zod';
import { createApp } from '../../src/app.ts';
import { errorHandler, notFoundHandler } from '../../src/lib/errors.ts';
import { ProblemSchema, notFound } from '../../src/lib/problem.ts';

function expectProblem(res: Response, status: number, slug: string) {
  expect(res.status).toBe(status);
  expect(res.headers['content-type']).toMatch(/^application\/problem\+json/);
  const problem = ProblemSchema.parse(res.body);
  expect(problem.status).toBe(status);
  expect(problem.type).toBe(`https://api.sf/problems/${slug}`);
  return problem;
}

const ThingSchema = z.object({ name: z.string().min(1), size: z.number().int() });

/** A throwaway app with one validating route, wired like createApp(). */
function appWithRoute() {
  const app = express();
  app.use(express.json());
  app.post('/v1/things', (req, res) => {
    const body = ThingSchema.parse(req.body);
    res.status(201).json(ThingSchema.parse(body));
  });
  app.get('/v1/things/:thingId', (req) => {
    throw notFound(`thing ${String(req.params.thingId)} not found`);
  });
  app.get('/v1/boom', () => {
    throw new Error('secret internals');
  });
  app.use(notFoundHandler);
  app.use(errorHandler);
  return app;
}

describe('createApp error handling', () => {
  afterEach(() => {
    vi.restoreAllMocks();
  });

  it('answers unknown routes with a 404 problem', async () => {
    const res = await request(createApp()).get('/v1/does-not-exist?x=1');
    const problem = expectProblem(res, 404, 'not-found');
    expect(problem.instance).toBe('/v1/does-not-exist?x=1');
    expect(problem.detail).toContain('GET /v1/does-not-exist');
  });

  it('answers malformed JSON with a 400 problem', async () => {
    const res = await request(createApp()).post('/v1/anything').set('Content-Type', 'application/json').send('{"name":');
    expectProblem(res, 400, 'malformed-json');
  });

  it('maps a ZodError to a 422 problem listing each issue', async () => {
    const res = await request(appWithRoute()).post('/v1/things').send({ name: '', size: 1.5 });
    const problem = expectProblem(res, 422, 'validation');
    expect(problem.detail).toContain('name: ');
    expect(problem.detail).toContain('size: ');
    expect(problem.detail.split('; ')).toHaveLength(2);
  });

  it('passes valid bodies through', async () => {
    const res = await request(appWithRoute()).post('/v1/things').send({ name: 'a', size: 2 });
    expect(res.status).toBe(201);
    expect(res.body).toEqual({ name: 'a', size: 2 });
  });

  it('sends a thrown HttpProblem with its own status', async () => {
    const res = await request(appWithRoute()).get('/v1/things/42');
    const problem = expectProblem(res, 404, 'not-found');
    expect(problem.detail).toBe('thing 42 not found');
    expect(problem.instance).toBe('/v1/things/42');
  });

  it('hides unexpected errors behind a 500 problem without a stack', async () => {
    const stderr = vi.spyOn(process.stderr, 'write').mockImplementation(() => true);
    const res = await request(appWithRoute()).get('/v1/boom');
    const problem = expectProblem(res, 500, 'internal');
    expect(JSON.stringify(res.body)).not.toContain('secret internals');
    expect(problem.detail).not.toContain('at ');
    expect(stderr.mock.calls.map(([chunk]) => String(chunk)).join('')).toContain('secret internals');
  });
});
